obj_codes.gml:
if (init == 0)
{
    switch (image_index)
    {
        case 1:
            doorRoom = room + ROOM_INITIALIZE;
            break;
        case 2:
            doorRoom = room - ROOM_INITIALIZE;
            break;
        case 3:
            doorRoom = room + room_title_placeholder;
            break;
        case 4:
            doorRoom = room - room_title_placeholder;
            break;
        case 5:
            doorRoom = room + room_battletest;
            break;
        case 6:
            doorRoom = room - room_battletest;
            break;
        default:
            break;
    }
    if (image_index != 0)
    {
        doorEntrance = image_index;
    }
    if (doorSpecial != "none")
    {
        if (global.chapter == 3)
        {
            if (doorSpecial == "pc")
            {
                if (room == room_dw_green_room)
                {
                    if (global.plot >= 280)
                    {
                        doorFadeMusic = false;
                        doorRoom = room_dw_puzzlecloset_3;
                    }
                }
            }
        }
    }
    init = 1;
}

global.interact = 3;
if (!i_ex(obj_fadeout))
{
    instance_create(0, 0, obj_fadeout);
}
if (touched == 0)
{
    alarm[2] = 8;
    event_user(8);
    touched = 1;
}

